    @TokenProvider.provide_access_token
    def upload_alarms(self, integrated_ids, timeout, run_async=False):
        """
        Starts alarm upload for each of the integrated element ids.

        :param list[str] integrated_ids: List of integrated element ids.
        :param int timeout: Time to wait for the response of the current operation.
        :param bool run_async: If set to ``True`` keyword will not wait for operation result and return
        ``OperationStartResponse`` object that contains ``operation_id`` attribute instead.


        :return list[OperationStatusResponse]: Every ``OperationStatusResponse`` contains
            ``operation_id``, ``status`` and ``timestamp`` attributes.
            Example the same as for :meth:`get_operation_status`.
        """
        response = self.operations.upload_alarms(integrated_ids=integrated_ids)
        if run_async:
            return response
        return self.wait_for_operation_status(response.operation_id, timeout)

    @TokenProvider.provide_access_token
    def import_plan(self, path_to_plan, **kwargs):
        """
        Import configuration plan in RAML/CM format to NOM.

        Upon successful import, the plan with given name will be generally available for use in other NOM functionalities.

        :param str path_to_plan: Path to file containing a plan in RAML2.1 format.

        :keyword str name: User can optionally specify the plan name to store the file content under.
            If not provided, the plan name from inside RAML2 file will be used.
        :keyword str description: User can optionally provide a description for content and/or purpose of this plan.
        :keyword bool overwrite: By default importing plan with name already existing in NOM will be refused.
        :keyword str plan_type: This parameter is indicating what is the type of the plan.
            Plan type is used to differentiate plans for different use cases in NOM UI.
            By default the user is not expected to provide any information for this parameter.
        """
        self.operations.import_plan(path_to_plan, **kwargs)

    @TokenProvider.provide_access_token
    def export_plan(self, scope):
        """
        Export the entire actual configuration in RAML2.1 file format.

        This interface exports the entire actual configuration if no scopes are provided,
        If scopes are provided, only those managed objects together with their descendants are exported.

        :param list scope: List of managed object DNs of which subtrees should be included in export.
            If not specified, i.e. array is empty, entire actual configuration will be exported.
            If provided, the value has to be managed object's distinguish name in URL encoded format.
            For example, ``MRBTS-1234`` or ``PLMN-PLMN/MRBTS-1234``.

        :return str: The configuration content in RAML2.1 format.
        """
        return self.operations.export_plan(scope)

    @TokenProvider.provide_access_token
    def integrate_ne(self, plan_name, reintegrate, timeout):
        """
        Integrate network elements defined in a given plan.

        This operation will process all managed objects in the plan and trigger NE-NOM integration sequences for
        all of them in parallel. Supported are only managed object classes from com.nokia.nms.integration adaptation.
        All other objects will be ignored.

        :param str plan_name: Name of the plan whose managed objects are to be integrated by this execution.
        :param int timeout: Time to wait for the response of the current operation.
        :param bool reintegrate: Reintegrate in case the NE is already integrated to NOM.

        :return list[OperationStatusResponse]: Every ``OperationStatusResponse`` contains
            ``operation_id``, ``status`` and ``timestamp`` attributes.
            Example the same as for :meth:`get_operation_status`.
        """
        response = self.operations.integrate_ne(plan_name=plan_name, reintegrate=reintegrate)
        return self.wait_for_operation_status(response.operation_id, timeout)

    @TokenProvider.provide_access_token
    def deintegrate_ne(self, plan_name, timeout=60, purge_data=False, force_deintegration=False, run_async=False):
        """
        Deintegrate network elements defined in a given plan.

        This operation will process all managed objects in the plan and trigger NE-NOM deintegration sequences for
        all of them in parallel. Supported are only managed object classes from com.nokia.nms.deintegration adaptation.
        All other objects will be ignored.

        :param str plan_name: Name of the plan whose managed objects are to be deintegrated by this execution.
        :param int timeout: Time to wait for the response of the current operation.
        :param bool purge_data: Delete all alarms and other associated data about the network element
        :param bool force_deintegration: Force the deintegration to continue even if some problems occur.
        :param bool run_async: If set to ``True`` keyword will not wait for operation result and return
            ``OperationStartResponse`` object that contains ``operation_id`` attribute instead.

        :return list[OperationStatusResponse]: Every ``OperationStatusResponse`` contains
            ``operation_id``, ``status`` and ``timestamp`` attributes.
            Example the same as for :meth:`get_operation_status`.
        """
        response = self.operations.deintegrate_ne(plan_name, purge_data, force_deintegration)
        if run_async:
            return response
        return self.wait_for_operation_status(response.operation_id, timeout)

    @TokenProvider.provide_access_token
    def download_plan(self, plan_name, timeout):
        """
        Initiate plan download for given plan content.
        It is expected that plan will contain only NE3S capable integrated elements.

        :param str plan_name: Name of the plan whose managed objects are to be integrated by this execution.
        :param str timeout: Time to wait for the response of the current operation.

        :return list[OperationStatusResponse]: Every ``OperationStatusResponse`` contains
            ``operation_id``, ``status`` and ``timestamp`` attributes.
            Example the same as for :meth:`get_operation_status`.
        """
        response = self.deprecated.download_plan(plan_name)
        return self.wait_for_operation_status(response.operation_id, timeout)

    @TokenProvider.provide_access_token
    def validate_plan(self, plan_name, timeout):
        """
        Initiate plan validation for given plan content.
        It is expected that plan will contain only NE3S capable integrated elements.

        :param str plan_name: Name of the plan whose managed objects are to be integrated by this execution.
        :param int timeout: Time to wait for the response of the current operation.

        :return list[OperationStatusResponse]: Every ``OperationStatusResponse`` contains
            ``operation_id``, ``status`` and ``timestamp`` attributes.
            Example the same as for :meth:`get_operation_status`.
        """
        response = self.deprecated.validate_plan(plan_name)
        return self.wait_for_operation_status(response.operation_id, timeout)

    @TokenProvider.provide_access_token
    def validate_plan_offline(self, plan_name, timeout=60, ne3s_dedicated=True):
        """
        Request offline validation for both NE3S and netconf based elements supporting offline validation
        in the given CM plan.

        :param str plan_name: Name of the plan whose managed objects are to be validated by this execution.
        :param int timeout: Time to wait for the response of the current operation.
        :param bool ne3s_dedicated: If set to ``True``, offline validation is limited to NE3S based elements and
            `operations/v1/request/start/ne3s-plan-validate-offline` endpoint is called.
            Otherwise `operations/v1/request/start/plan-validate-offline` endpoint is called.

        :return list[OperationStatusResponse]: Every ``OperationStatusResponse`` contains
            ``operation_id``, ``status`` and ``timestamp`` attributes.
            Example the same as for :meth:`get_operation_status`.
        """
        if ne3s_dedicated:
            response = self.operations.validate_plan_offline_ne3s_dedicated(plan_name=plan_name)
        else:
            response = self.operations.validate_plan_offline(plan_name=plan_name)
        return self.wait_for_operation_status(response.operation_id, timeout)

    @TokenProvider.provide_access_token
    def activate_plan(self, plan_name, timeout):
        """
        Initiate plan activation for given plan content.
        It is expected that plan will contain only NE3S capable integrated elements.

        :param str plan_name: Name of the plan whose managed objects are to be integrated by this execution.
        :param int timeout: Time to wait for the response of the current operation.

        :return list[OperationStatusResponse]: Every ``OperationStatusResponse`` contains
            ``operation_id``, ``status`` and ``timestamp`` attributes.
            Example the same as for :meth:`get_operation_status`.
        """
        response = self.deprecated.activate_plan(plan_name)
        return self.wait_for_operation_status(response.operation_id, timeout)

    @TokenProvider.provide_access_token
    def provision_plan(self, plan_name, rollback_plan_generation=False, timeout=10, run_async=False):
        """
        Initiate plan provisioning for given plan content.
        It is expected that plan will contain only NE3S capable integrated elements.

        :param str plan_name: Name of the plan whose managed objects are to be integrated by this execution.
        :param bool rollback_plan_generation: If set to true a backup plan will be auto-generated, which will be
            reverting changes done by the plan to their present actual values.
        :param int timeout: Time to wait for the response of the current operation.
        :param bool run_async: If set to ``True`` keyword will not wait for operation result and return
            ``OperationStartResponse`` object that contains ``operation_id`` attribute instead.

        :return list[OperationStatusResponse]: Every ``OperationStatusResponse`` contains
            ``operation_id``, ``status`` and ``timestamp`` attributes.
            Example the same as for :meth:`get_operation_status`.
        """
        response = self.deprecated.provision_plan(plan_name, rollback_plan_generation)
        if run_async:
            return response
        return self.wait_for_operation_status(response.operation_id, timeout)

    @TokenProvider.provide_access_token
    def remove_plans(self, plan_type, before, plan_name_regex=None, timeout=10):
        """
        Remove plans from the system based on plan type and timestamp.
        Note that this operation removes data irreversibly!

        :param str plan_type: Type of the plans whose managed objects are to be removed by this execution.
        :param str before: Only plans whose managed objects are older than given timestamp
            are to be removed by this execution.
        :param str plan_name_regex: If set only plans with matching to given regex name
            are to be removed by this execution.
        :param int timeout: Time to wait for the response of the current operation.

        :return list[OperationStatusResponse]: Every ``OperationStatusResponse`` contains
            ``operation_id``, ``status`` and ``timestamp`` attributes.
            Example the same as for :meth:`get_operation_status`.
        """
        response = self.operations.remove_plans(
            plan_type=plan_type, before=before, plan_name_regex=plan_name_regex)
        return self.wait_for_operation_status(response.operation_id, timeout)

    @TokenProvider.provide_access_token
    def activate_autoconfiguration(self, plan_name, apply_templates, validate, timeout=10, run_async=False, **kwargs):
        """
        Depending on boolean flags used, this operation applies templates, performs offline validation, and activates
        configuration which will then be used for NE identification during autoconnection and provisioned
        during autoconfiguration phase.

        Once the operation is finished successfully, Plug and Play process can be triggered from Network Element.

        :param str plan_name: List of integrated element ids.
        :param bool apply_templates: If set to ``True``, complement plan operation will be performed.
        :param bool validate: If set to ``True``, offline plan validation will be performed.
        :param int timeout: Time to wait for the response of the current operation.
        :param bool run_async: If set to ``True`` keyword will not wait for operation result and return
            ``OperationStartResponse`` object that contains ``operation_id`` attribute instead.

        :keyword bool overwrite** (bool) - Users can optionally specify if already activated configuration should be overwritten.
            If not provided, the operation will fail for already activated configurations.
        :keyword str private_key: This is a private key in PEM format.
            If provided, the operation will use it to decrypt all OAM link password attributes stored as parameters
            in the planned managed objects. If provided, the operation expects all such attributes to be encrypted
            with the RSA algorithm base64 form. All the new line characters in .pem content should be converted to
            "\\\\n" and then concatenate all the PEM lines as one long string. The following command can be used for
            the conversion: ``awk 'NF {sub(/\\r/, ""); printf "%s\\n",$0;}' pem-certificate-name.pem``
            If provided with empty value, the operation will fail. If not provided, the operation expects all such
            parameters to be in plain text form.
        :keyword str user_defined_name: User can provide own name for this operation execution.
        :keyword str user_defined_description: User can provide with own description about this operation execution.
        :keyword bool deploy_cnf: If set to ``True``, deploy-planned-cnfs operation will be performed.

        :return list[OperationStatusResponse]: Every ``OperationStatusResponse`` contains
            ``operation_id``, ``status`` and ``timestamp`` attributes.
            Example the same as for :meth:`get_operation_status`.
        """
        response = self.operations.activate_autoconfiguration(
            plan_name=plan_name, apply_templates=apply_templates, validate=validate, **kwargs)
        if run_async:
            return response
        return self.wait_for_operation_status(response.operation_id, timeout)

