    @TokenProvider.provide_access_token
    def provision_sw(self, integrated_ids, ne_sw_version, download=True, activate=True, timeout=1800,
                     run_async=False, provision=None, precheck=None, postcheck=None):
        """
        Provision, download or activate software for given network elements.

        Provision is performed when both flags, download and activate are set to ``True``.

        :param list[str] integrated_ids: List of integrated network elements, e.g. ``['MRBTS-1234']``
        :param str ne_sw_version: Network element software version, e.g.: ``5G20A_GNB_0009_001800_001514``
        :param bool download: Specify whether download of given sw version has to be performed.
        :param bool activate: Specify whether activation of given sw version has to be performed.
        :param int timeout: Timeout for SW provision, download or activation operation.
        :param bool run_async: If set to ``True`` keyword will not wait for operation result and return
            ``OperationStartResponse`` object that contains ``operation_id`` attribute instead.
        :param bool provision: Specify whether atomic provision of given sw version has to be performed.
            If set to ``True``, other flags are ignored.
        :param str precheck: Specifies software pre-check type before download, activate, or provision.
            Allowed values: ``fullCheck``, ``upgradeCheck`` or ``rebootCheck``.
        :param bool postcheck: Specifies whether software post-check is required after
            `download`, `activate`, or `provision`.

        :return list[OperationStatusResponse]: Every ``OperationStatusResponse`` contains
            ``operation_id``, ``status`` and ``timestamp`` attributes.
            Example the same as for :meth:`get_operation_status`.
        """
        response = self.operations.provision_sw(
            integrated_ids=integrated_ids, ne_sw_version=ne_sw_version, download=download,
            activate=activate, provision=provision, precheck=precheck, postcheck=postcheck)
        if run_async:
            return response
        return self.wait_for_operation_status(response.operation_id, timeout, retry_interval=30)

    def wait_for_operation_status(self, operation_id, timeout, retry_interval=1):
        """
        Check operation status until it is finished or timeout is exceeded.

        :param string operation_id: Id of operation.
        :param int timeout: Time to wait for the response of the current operation.
        :param Union[int,str] retry_interval: Time to wait between operation status checks.

        :return list[OperationStatusResponse]: Every ``OperationStatusResponse`` contains
            ``operation_id``, ``status`` and ``timestamp`` attributes.
            Example the same as for :meth:`get_operation_status`.
        """
        start = time.time()
        while True:
            try:
                response = self.get_operation_status([operation_id])
                status = response[-1].status if response else None
            except ApiException as e:
                msg = "get_operation_status call failed for operationId: %s. NOM Open API is unstable! Exception: %s" % (operation_id, str(e))
                logger.warning(msg)
                status = None
            if status and self._is_operation_completed(operation_id, status):
                return response
            if time.time() - start > timeout:
                exc_msg = 'Timeout exceeded, operation_id: {}, status: {}'
                raise TimeoutError(exc_msg.format(operation_id, status))
            time.sleep(retry_interval)

    @staticmethod
    def _is_operation_completed(operation_id, status):
        negative_statuses = ['failed', 'interrupted']
        if status == 'finished':
            return True
        elif status in negative_statuses:
            exc_msg = 'operation_id: {}, status: {}'
            raise NegativeOperationStatus(exc_msg.format(operation_id, status))
        return False

