    @TokenProvider.provide_access_token
    def add_managed_objects(self, conf_id, managed_objects):
        """
        Add one or more managed objects to a configuration.

        Add a new managed object or objects to an existing configuration.
        Currently, this method supports the update of PLAN type configurations only.
        For `PLAN` type configurations, managed objects can contain parameters whose values are to be changed.

        Usage example:
            >>> from taf.nms.nom import nom
            >>>
            >>> nom_rf_interface = nom()
            >>> nom_rf_interface.connect_to(...)
            >>>
            >>> new_plan = nom_rf_interface.create_empty_plan(...)
            >>> conf_id = new_plan['info']['conf_id']
            >>>
            >>> mos = ['MRBTS-1234']
            >>> actual_mos = nom_rf_interface.get_managed_objects_parameters(1, mos)
            >>>
            >>> new_mos = actual_mos['result']
            >>> new_mos[0]['operation'] = 'UPDATE'
            >>> new_mos[0]['parameters']['btsName'] = 'new better name'
            >>> nom_rf_interface.add_managed_objects(conf_id, new_mos)

        :param int conf_id: PLAN type configuration id.
        :param list[dict] managed_objects: Managed objects to be added.
            Every dict must contain the following keys:

                - **moId/mo_id** (str): Managed object identifier.
                - **moClass/mo_class** (dict): Must contain proper ``id`` and ``version`` keys.
                - **planOperation/operation** (str): Allowed values: ``CREATE``, ``UPDATE``, ``DELETE``.
                - **parameters** (dict): Must contain only parameters related to the set ``moClass/mo_class``.

            E.g.::

                [
                    {
                      "mo_id": "MRBTS-1234",
                      "mo_class": {
                        "id": "com.nokia.srbts:MRBTS",
                        "version": "SBTS20C_2006_001"
                      },
                      "operation": "UPDATE",
                      "parameters": {
                        "btsName": "new value"
                      }
                    }
                ]
        """
        self.cm.add_managed_objects(conf_id, managed_objects)

