    @TokenProvider.provide_access_token
    def import_legacy_netact_plan(self, raml_file_path, **kwargs):
        """
        Import a plan content containing data in NetAct (Legacy in UI terminology) parameter model in RAML2.1 format.

        Supported file types are xml and compressed zip format. Upon successful import, the plan with the given name
        will be available for use in other Nokia Network Operations Master operations.

        :param str raml_file_path: Path to RAML file.

        :keyword str name: Plan name to store the file content under, if not provided,
            the plan name from inside the RAML2 file will be used.
        :keyword str description: Description for the content and/or purpose of this plan.
        :keyword bool overwrit: By default, importing a plan with a name that already exists will be refused.
            This is to prevent accidental updates of plan contents. To overwrite an existing plan,
            the user has to set this parameter to true. If the user provides this parameter and
            there is no plan with the same name, there is no impact to import operation.
        :keyword str plan_type: This parameter indicates the type of the plan.
            The plan type is used to differentiate plans for different use cases in NOM REST API.
            By default, the user is not expected to provide any information for this parameter.
        """
        self.operations.import_legacy_netact_plan(raml_file_path, **kwargs)

